<script setup>
import {computed,ref,watch} from 'vue'
import {queenSteps,queenConflicts,queenNeighbors} from '../services/local-search.mjs'
import SimulationControls from './SimulationControls.vue'
import SearchTraceCode from './SearchTraceCode.vue'
const props=defineProps({mode:{type:String,default:'hill'}})
const mode=ref(props.mode),n=ref(8),seed=ref(7),rows=ref([1,3,6,3,7,4,4,1]),step=ref(0),column=ref(0)
const trace=computed(()=>Array.from(queenSteps({rows:rows.value,mode:mode.value,seed:seed.value,budget:80}))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)])
const key=computed(()=>JSON.stringify([rows.value,mode.value,seed.value]))
watch(key,()=>step.value=0);watch(n,()=>{rows.value=Array.from({length:n.value},(_,i)=>i%n.value);column.value=0})
const costs=computed(()=>{const a=Object.fromEntries(queenNeighbors(state.value.rows).filter(x=>x.column===column.value).map(x=>[x.row,x.cost]));a[state.value.rows[column.value]]=state.value.cost;return a})
function edit(c,r){rows.value=state.value.rows.slice();rows.value[c]=r;column.value=c;step.value=0}
function reset(){rows.value=n.value===8?[1,3,6,3,7,4,4,1]:[...Array(n.value).keys()];step.value=0}
const message=computed(()=>{const s=state.value;if(s.phase==='success')return 'Đã tìm được cấu hình không có cặp hậu tấn công nhau.';if(s.phase==='local')return 'Dừng cục bộ: Không có phép dời một quân nào giảm số cặp xung đột.';if(s.phase==='budget')return 'Hết 80 vòng. Chưa tìm thấy nghiệm không có nghĩa bài toán vô nghiệm.';if(s.phase==='candidate')return `Đề xuất dời hậu cột ${s.next.column+1} đến hàng ${s.next.row+1}, tạo ${s.next.cost} cặp xung đột.`;if(s.phase==='reject')return `Từ chối bước xấu. Xác suất nhận ${s.probability.toFixed(4)}, số ngẫu nhiên ${s.draw.toFixed(4)}.`;if(s.phase==='move')return mode.value==='minconflicts'?'Chọn ngẫu nhiên một cột đang xung đột, rồi chọn ngẫu nhiên trong các hàng có ít xung đột nhất. Có thể giữ nguyên hàng.':'Cập nhật cấu hình và kỷ lục tốt nhất. Phá hòa leo đồi theo cột rồi hàng tăng dần.';return 'Mỗi cột có đúng một quân hậu. Bấm vào ô để đổi cấu hình ban đầu. Hàng được đánh số từ trên xuống.'})
</script>
<template><section class="math-lab local-queens" aria-label="Mô phỏng tìm kiếm cục bộ n quân hậu"><div class="queen-settings"><label>Kích thước<select v-model.number="n"><option v-for="i in [4,5,6,8,10]" :key="i">{{ i }}</option></select></label><label>Thuật toán<select v-model="mode"><option value="hill">Leo đồi</option><option value="anneal">Tôi luyện mô phỏng</option><option value="minconflicts">Min-conflicts</option></select></label><label>Hạt giống<select v-model.number="seed"><option v-for="i in [1,7,23,42]" :key="i">{{ i }}</option></select></label><button type="button" @click="reset">Cấu hình mẫu</button></div><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><div class="queen-board" :style="{'--n':n}" role="group" aria-label="Bàn cờ có thể chỉnh bằng chuột, chạm hoặc bàn phím"><template v-for="r in n" :key="r"><button v-for="c in n" :key="c" type="button" :class="{dark:(r+c)%2===1,queen:state.rows[c-1]===r-1,proposed:state.next?.column===c-1&&state.next?.row===r-1}" :aria-label="`Cột ${c}, hàng ${r}${state.rows[c-1]===r-1?', có hậu':''}. Đặt hậu tại đây`" @click="edit(c-1,r-1)">{{ state.rows[c-1]===r-1?'♛':'' }}</button></template></div><div class="queen-results"><span>Hiện tại h = {{ state.cost }}</span><span>Tốt nhất h = {{ state.bestCost }}</span><span>Láng giềng: {{ n*(n-1) }}</span></div><p class="queen-status" role="status">{{ message }}</p><details><summary>Xem chi phí khi dời một hậu</summary><label>Cột quan sát<select v-model.number="column"><option v-for="(_,i) in rows" :key="i" :value="i">{{ i+1 }}</option></select></label><div class="queen-costs"><span v-for="r in n" :key="r">Hàng {{ r }}: {{ costs[r-1] }}</span></div><p>Các con số đếm cặp hậu cùng hàng hoặc cùng đường chéo. Hàng hiện tại cũng được hiển thị để so sánh, nhưng không tạo một láng giềng mới.</p><p>Cấu hình tốt nhất, hàng theo cột: {{ state.best.map(x=>x+1).join(', ') }}.</p></details><SearchTraceCode name="queenSteps" :phase="state.phase"/></section></template>
<style scoped>
.local-queens{min-width:0}.queen-settings{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.local-queens label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.local-queens select,.queen-settings button{min-height:44px;padding:8px;border:1px solid var(--control);border-radius:var(--radius);color:var(--ink);background:var(--paper);font:inherit}.queen-board{display:grid;grid-template-columns:repeat(var(--n),1fr);max-width:440px;margin:20px auto;border:1px solid var(--ink-2)}.queen-board button{display:grid;place-items:center;aspect-ratio:1;min-width:0;padding:0;border:0;background:var(--paper);color:var(--ink);font-size:clamp(20px,5vw,40px);cursor:pointer}.queen-board button.dark{background:var(--tim-soft)}.queen-board button.proposed{box-shadow:inset 0 0 0 3px var(--xanh)}.queen-board button:focus-visible{outline:3px solid var(--tim);outline-offset:-3px}.queen-results,.queen-costs{display:flex;flex-wrap:wrap;gap:8px}.queen-results span,.queen-costs span{padding:8px;background:var(--paper);border:1px solid var(--rule);border-radius:var(--radius);font:var(--fs-small)/1.6 var(--font-ui)}.queen-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}summary{min-height:44px;cursor:pointer}select:focus-visible,.queen-settings button:focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:480px){.queen-settings{display:grid;grid-template-columns:1fr 1fr}.queen-board button{min-height:0;font-size:28px}}
</style>
